package dev.relay.domain;
import com.fasterxml.jackson.databind.*;import dev.relay.repo.WorkflowRepository;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.*;
@Service public class OrderFulfillmentService {
 private final WorkflowRepository repo;private final JdbcTemplate jdbc;private final ObjectMapper mapper;public OrderFulfillmentService(WorkflowRepository repo,JdbcTemplate jdbc,ObjectMapper mapper){this.repo=repo;this.jdbc=jdbc;this.mapper=mapper;}
 public Workflow create(CreateOrderRequest o){Map<String,Object> in=new LinkedHashMap<>();in.put("orderId",o.orderId());in.put("customerName",o.customerName());in.put("email",o.email());in.put("sku",o.sku());in.put("quantity",o.quantity());in.put("amount",o.amount());in.put("paymentScenario",o.paymentScenario().name());var steps=List.of(new CreateWorkflowRequest.Step("reserve-inventory",Map.of()),new CreateWorkflowRequest.Step("charge-payment",Map.of()),new CreateWorkflowRequest.Step("create-shipment",Map.of()),new CreateWorkflowRequest.Step("send-confirmation",Map.of()));return repo.create(new CreateWorkflowRequest("order-fulfillment",o.orderId(),in,steps,3));}
 public List<OrderRow> dashboardOrders(){List<OrderRow> rows=new ArrayList<>();for(Workflow w:repo.all()){if(!w.workflowType().equals("order-fulfillment"))continue;try{JsonNode j=mapper.readTree(w.input());String payment=scalar("select status from payments where workflow_id=?",w.id());String tracking=scalar("select tracking_code from shipments where workflow_id=?",w.id());String reservation=scalar("select sku||' × '||quantity||' ('||status||')' from inventory_reservations where workflow_id=?",w.id());rows.add(new OrderRow(w,j.path("orderId").asText(),j.path("customerName").asText(),j.path("sku").asText(),j.path("quantity").asInt(),j.path("amount").asText(),payment,reservation,tracking));}catch(Exception ignored){}}return rows;}
 private String scalar(String sql,UUID id){return jdbc.query(sql,rs->rs.next()?rs.getString(1):"—",id);}
 public OrderMetrics metrics(){List<OrderRow> o=dashboardOrders();return new OrderMetrics(o.size(),o.stream().filter(x->Set.of(WorkflowStatus.RUNNING,WorkflowStatus.PENDING,WorkflowStatus.RETRY_WAIT).contains(x.workflow().status())).count(),o.stream().filter(x->x.workflow().status()==WorkflowStatus.SUCCEEDED).count(),o.stream().filter(x->x.workflow().status()==WorkflowStatus.FAILED).count());}
 public record OrderRow(Workflow workflow,String orderId,String customerName,String sku,int quantity,String amount,String payment,String reservation,String tracking){}public record OrderMetrics(long total,long active,long completed,long failed){}
}
